package service

import (
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	Users = make(map[string]User)
	Mutex sync.RWMutex
)

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	Mutex.RLock()
	defer Mutex.RUnlock()
	var list []User
	for _, u := range Users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user with a generated ID
func CreateUser(u User) (User, error) {
	Mutex.Lock()
	defer Mutex.Unlock()
	u.ID = uuid.New().String()
	Users[u.ID] = u
	return u, nil
}

// GetUserByID retrieves a user by their ID
func GetUserByID(id string) (User, bool) {
	Mutex.RLock()
	defer Mutex.RUnlock()
	u, ok := Users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"main/internal/service"
)

// HandleUsers handles requests for /users endpoint
func HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		list := service.GetAllUsers()
		json.NewEncoder(w).Encode(list)

	case http.MethodPost:
		var u service.User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		createdUser, err := service.CreateUser(u)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(createdUser)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID handles requests for /users/{id} endpoint
func HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		u, ok := service.GetUserByID(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"main/internal/api"
)

func main() {
	http.HandleFunc("/users", api.HandleUsers)
	http.HandleFunc("/users/", api.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"experiment/internal/api"
	"experiment/internal/service"
)

func TestMain(m *testing.M) {
	m.Run()
}

func TestUserAPI(t *testing.T) {
	// Reset the service state for a clean test run
	service.Mutex.Lock()
	service.Users = make(map[string]service.User)
	service.Mutex.Unlock()

	// Create a test server
	rr := httptest.NewRecorder()
	req, _ := http.NewRequest("GET", "/users", nil)

	// Test POST /users
	user := service.User{Name: "Test User", Email: "test@example.com"}
	jsonUser, _ := json.Marshal(user)
	req, _ = http.NewRequest("POST", "/users", bytes.NewBuffer(jsonUser))
	api.HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusCreated)
	}

	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if createdUser.Name != user.Name || createdUser.Email != user.Email || createdUser.ID == "" {
		t.Errorf("handler returned unexpected user: got %+v", createdUser)
	}

	// Test GET /users
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", "/users", nil)
	api.HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if len(users) != 1 || users[0].ID != createdUser.ID {
		t.Errorf("handler returned unexpected users list: got %+v", users)
	}

	// Test GET /users/{id}
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", fmt.Sprintf("/users/%s", createdUser.ID), nil)
	api.HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var fetchedUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&fetchedUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if fetchedUser.ID != createdUser.ID {
		t.Errorf("handler returned unexpected user by ID: got %+v", fetchedUser)
	}

	// Test GET /users/{non-existent-id}
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", "/users/nonexistent", nil)
	api.HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code for non-existent user: got %v want %v", status, http.StatusNotFound)
	}
}
